window.__EXTRA__=[{"s":"Maths (Higher)","t":"Number: surds & indices","q":"Simplify root(75). Give your answer as a root b where a and b are integers.","explain":"root(75) = root(25 x 3) = 5root(3), so a = 5.","type":"numeric","answer":5,"tolerance":0},{"s":"Maths (Higher)","t":"Number: surds & indices","q":"Which of the following is equal to 2^(-3)?","explain":"A negative index means take the reciprocal: 2^(-3) = 1/2^3 = 1/8.","type":"mcq","options":["6","1/6","1/8","-8"],"answer":2},{"s":"Maths (Higher)","t":"Number: surds & indices","q":"Simplify (root(5) + 1)(root(5) - 1). Give a single integer.","explain":"Difference of two squares: (root(5))^2 - 1^2 = 5 - 1 = 4.","type":"short","accept":["4"]},{"s":"Maths (Higher)","t":"Number: surds & indices","q":"27^(2/3) = 9","explain":"27^(1/3) = 3, then 3^2 = 9, so 27^(2/3) = 9.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"Algebra: quadratics","q":"Solve x^2 - 5x + 6 = 0. Which pair of solutions is correct?","explain":"Factorises as (x - 2)(x - 3) = 0, giving x = 2 and x = 3.","type":"mcq","options":["x = 1 and x = 6","x = 2 and x = 3","x = -2 and x = -3","x = -1 and x = 6"],"answer":1},{"s":"Maths (Higher)","t":"Algebra: quadratics","q":"The equation x^2 + 6x + k = 0 has exactly one solution. What is the value of k?","explain":"For one solution, discriminant = 0: 6^2 - 4k = 0, so k = 9.","type":"numeric","answer":9,"tolerance":0},{"s":"Maths (Higher)","t":"Algebra: quadratics","q":"Write x^2 + 4x - 1 in the form (x + a)^2 + b. What is the value of b?","explain":"Completing the square: (x + 2)^2 - 4 - 1 = (x + 2)^2 - 5, so b = -5.","type":"short","accept":["-5"]},{"s":"Maths (Higher)","t":"Algebra: quadratics","q":"The quadratic formula gives x = (-b +/- root(b^2 - 4ac)) / 2a for ax^2 + bx + c = 0.","explain":"This is the standard quadratic formula.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"Geometry: Pythagoras & trig","q":"A right-angled triangle has legs of length 9 cm and 12 cm. What is the length of the hypotenuse in cm?","explain":"root(9^2 + 12^2) = root(81 + 144) = root(225) = 15 cm.","type":"numeric","answer":15,"tolerance":0},{"s":"Maths (Higher)","t":"Geometry: Pythagoras & trig","q":"In a right-angled triangle, the opposite side is 7 cm and the hypotenuse is 10 cm. Which expression gives the angle opposite the 7 cm side?","explain":"sin(angle) = opposite/hypotenuse = 7/10, so angle = sin^-1(0.7).","type":"mcq","options":["sin^-1(7/10)","cos^-1(7/10)","tan^-1(7/10)","sin^-1(10/7)"],"answer":0},{"s":"Maths (Higher)","t":"Geometry: Pythagoras & trig","q":"Find the exact value of cos(60). Give your answer as a decimal.","explain":"cos(60) = 1/2 = 0.5; this is a standard exact value.","type":"numeric","answer":0.5,"tolerance":0},{"s":"Maths (Higher)","t":"Geometry: Pythagoras & trig","q":"In a right-angled triangle with hypotenuse 5 and one leg 4, the other leg is 3.","explain":"root(5^2 - 4^2) = root(25 - 16) = root(9) = 3.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"Ratio & proportion: compound measures","q":"A car travels 150 km in 2.5 hours. What is its average speed in km/h?","explain":"Speed = distance / time = 150 / 2.5 = 60 km/h.","type":"numeric","answer":60,"tolerance":0},{"s":"Maths (Higher)","t":"Ratio & proportion: compound measures","q":"A piece of metal has mass 480 g and volume 60 cm^3. What is its density?","explain":"Density = mass / volume = 480 / 60 = 8 g/cm^3.","type":"mcq","options":["4 g/cm^3","6 g/cm^3","8 g/cm^3","12 g/cm^3"],"answer":2},{"s":"Maths (Higher)","t":"Ratio & proportion: compound measures","q":"Pressure = Force / Area, so if force doubles and area halves, pressure becomes 4 times greater.","explain":"Doubling F and halving A gives 2F / (A/2) = 4F/A, so pressure quadruples.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"Probability","q":"A bag contains 3 red, 5 blue and 2 green counters. One counter is drawn at random. What is P(not red)?","explain":"P(not red) = 1 - 3/10 = 7/10.","type":"mcq","options":["3/10","7/10","5/10","8/10"],"answer":1},{"s":"Maths (Higher)","t":"Probability","q":"Two fair six-sided dice are rolled. What is the probability of getting a total of 7? Give your answer as a decimal to 4 d.p.","explain":"There are 6 ways to get total 7 out of 36 outcomes: 6/36 = 1/6 = 0.1667.","type":"numeric","answer":0.1667,"tolerance":0.001},{"s":"Maths (Higher)","t":"Probability","q":"If two events A and B are mutually exclusive, then P(A or B) = P(A) + P(B).","explain":"Mutually exclusive events cannot occur together, so the addition rule simplifies to P(A) + P(B).","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"Probability","q":"A fair coin is flipped three times. How many outcomes are in the sample space?","explain":"Each flip has 2 outcomes, so total = 2^3 = 8 outcomes.","type":"short","accept":["8"]},{"s":"Maths (Higher)","t":"percentages","q":"A laptop costs 840 after a 30% reduction. What was the original price in pounds?","explain":"840 = 70% of original, so original = 840 / 0.7 = 1200.","type":"numeric","answer":1200,"tolerance":0},{"s":"Maths (Higher)","t":"percentages","q":"A price increases from 250 to 275. What is the percentage increase?","explain":"Percentage increase = (25/250) x 100 = 10%.","type":"numeric","answer":10,"tolerance":0},{"s":"Maths (Higher)","t":"linear & simultaneous equations","q":"Solve 4x - 3 = 17. What is x?","explain":"4x = 20, so x = 5.","type":"numeric","answer":5,"tolerance":0},{"s":"Maths (Higher)","t":"linear & simultaneous equations","q":"Solve simultaneously: x + y = 10 and x - y = 4. What is x?","explain":"Adding the equations: 2x = 14, so x = 7.","type":"short","accept":["7"]},{"s":"Maths (Higher)","t":"sequences","q":"The nth term of a sequence is 4n - 1. What is the 10th term?","explain":"4(10) - 1 = 40 - 1 = 39.","type":"short","accept":["39"]},{"s":"Maths (Higher)","t":"sequences","q":"Find the nth term of the sequence: 5, 8, 11, 14, ...","explain":"Common difference is 3; first term is 5; nth term = 3n + 2.","type":"short","accept":["3n+2","3n + 2"]},{"s":"Maths (Higher)","t":"sequences","q":"The sequence with nth term 2n^2 - 1 has its 5th term equal to 49.","explain":"2(5)^2 - 1 = 2(25) - 1 = 50 - 1 = 49.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"sequences","q":"Which nth term formula produces the sequence 1, 4, 9, 16, 25, ...?","explain":"These are the square numbers, so nth term = n^2.","type":"mcq","options":["2n - 1","n^2","n + 3","3n - 2"],"answer":1},{"s":"Maths (Higher)","t":"straight-line graphs","q":"What is the gradient of the line with equation 3x + 2y = 12?","explain":"Rearranging: y = -3/2 x + 6, so gradient = -3/2.","type":"mcq","options":["3/2","-3/2","2/3","6"],"answer":1},{"s":"Maths (Higher)","t":"straight-line graphs","q":"A line passes through (0, 4) and has gradient 2. What is the y-coordinate when x = 3?","explain":"y = 2x + 4; when x = 3, y = 6 + 4 = 10.","type":"short","accept":["10"]},{"s":"Maths (Higher)","t":"straight-line graphs","q":"The lines y = 3x + 1 and y = 3x - 5 are parallel.","explain":"Parallel lines have equal gradients; both have gradient 3.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"inequalities","q":"Solve 3x - 4 > 11. What is the smallest integer value of x that satisfies this?","explain":"3x > 15, so x > 5; the smallest integer greater than 5 is 6.","type":"short","accept":["6"]},{"s":"Maths (Higher)","t":"inequalities","q":"Which of the following is the solution set to -2 <= 2x < 6?","explain":"Divide all parts by 2: -1 <= x < 3.","type":"mcq","options":["-4 <= x < 3","-1 <= x < 3","-1 < x <= 3","-4 < x <= 3"],"answer":1},{"s":"Maths (Higher)","t":"standard form","q":"Write 0.000045 in standard form as a x 10^n. What is n?","explain":"0.000045 = 4.5 x 10^(-5), so n = -5.","type":"numeric","answer":-5,"tolerance":0},{"s":"Maths (Higher)","t":"standard form","q":"Calculate (3 x 10^4) x (2 x 10^3). Give your answer in standard form.","explain":"3 x 2 = 6 and 10^4 x 10^3 = 10^7, giving 6 x 10^7.","type":"mcq","options":["5 x 10^7","6 x 10^7","6 x 10^12","5 x 10^12"],"answer":1},{"s":"Maths (Higher)","t":"standard form","q":"Write 7.2 x 10^3 as an ordinary number.","explain":"Moving the decimal 3 places right: 7.2 x 10^3 = 7200.","type":"short","accept":["7200"]},{"s":"Maths (Higher)","t":"area, volume & surface area","q":"A cone has base radius 3 cm and vertical height 4 cm. What is its volume in cm^3 as a multiple of pi? (V = 1/3 pi r^2 h) Give just the number before pi.","explain":"V = 1/3 x pi x 3^2 x 4 = 12pi cm^3.","type":"numeric","answer":12,"tolerance":0},{"s":"Maths (Higher)","t":"area, volume & surface area","q":"A trapezium has parallel sides of 6 cm and 10 cm, and perpendicular height 4 cm. What is its area in cm^2?","explain":"Area = 1/2 x (a + b) x h = 1/2 x 16 x 4 = 32 cm^2.","type":"numeric","answer":32,"tolerance":0},{"s":"Maths (Higher)","t":"circle theorems","q":"O is the centre of a circle. Angle AOB = 80 degrees. What is the inscribed angle ACB where C is on the major arc?","explain":"The inscribed angle is half the central angle subtended by the same arc: 80/2 = 40 degrees.","type":"mcq","options":["80 degrees","160 degrees","40 degrees","100 degrees"],"answer":2},{"s":"Maths (Higher)","t":"circle theorems","q":"Opposite angles of a cyclic quadrilateral add up to 180 degrees.","explain":"A standard circle theorem: opposite angles in a cyclic quadrilateral are supplementary.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"circle theorems","q":"A tangent meets a radius at the point of contact. What angle do they make?","explain":"A tangent to a circle is perpendicular to the radius at the point of contact.","type":"mcq","options":["45 degrees","60 degrees","90 degrees","180 degrees"],"answer":2},{"s":"Maths (Higher)","t":"sine & cosine rule","q":"In triangle ABC, a = 7, b = 9, C = 60 degrees. Use the cosine rule to find c^2.","explain":"c^2 = 7^2 + 9^2 - 2(7)(9)cos(60) = 49 + 81 - 63 = 67.","type":"mcq","options":["49","67","81","130"],"answer":1},{"s":"Maths (Higher)","t":"sine & cosine rule","q":"In triangle PQR, angle P = 30 degrees, p = 5 cm, q = 7 cm. Using the sine rule, what is sin(Q)?","explain":"sin(Q) = 7 x sin(30)/5 = 7 x 0.5 / 5 = 0.7.","type":"numeric","answer":0.7,"tolerance":0.0001},{"s":"Maths (Higher)","t":"vectors","q":"Vector a = (3, 4). What is |a|, the magnitude of a?","explain":"|a| = root(3^2 + 4^2) = root(25) = 5.","type":"short","accept":["5"]},{"s":"Maths (Higher)","t":"vectors","q":"If a = 2i + 3j and b = i - j, what is 2a - b?","explain":"2a = 4i + 6j; 2a - b = 4i + 6j - i + j = 3i + 7j.","type":"mcq","options":["3i + 4j","4i + 7j","3i + 7j","5i + 5j"],"answer":2},{"s":"Maths (Higher)","t":"transformations","q":"Triangle A is reflected in the y-axis. Point (3, -2) maps to which image point?","explain":"Reflecting in the y-axis negates the x-coordinate: (3, -2) maps to (-3, -2).","type":"mcq","options":["(-3, -2)","(3, 2)","(-3, 2)","(2, -3)"],"answer":0},{"s":"Maths (Higher)","t":"transformations","q":"A rotation of 180 degrees about the origin maps (x, y) to (-x, -y).","explain":"A 180-degree rotation about the origin negates both coordinates.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"transformations","q":"Shape B is an enlargement of shape A with scale factor 3. If a side of A is 4 cm, what is the corresponding side of B in cm?","explain":"Enlargement multiplies lengths by the scale factor: 4 x 3 = 12 cm.","type":"short","accept":["12"]},{"s":"Maths (Higher)","t":"averages from frequency tables","q":"A frequency table shows scores 1, 2, 3 with frequencies 4, 5, 1. What is the mean score?","explain":"Mean = (1x4 + 2x5 + 3x1) / 10 = 17/10 = 1.7.","type":"numeric","answer":1.7,"tolerance":0.05},{"s":"Maths (Higher)","t":"averages from frequency tables","q":"A grouped frequency table has classes 0-9, 10-19, 20-29 with frequencies 5, 8, 7. What is the modal class?","explain":"The modal class has the highest frequency; 10-19 has frequency 8.","type":"mcq","options":["0-9","10-19","20-29","15-19"],"answer":1},{"s":"Maths (Higher)","t":"direct & inverse proportion","q":"y is directly proportional to x^2. When x = 3, y = 36. What is y when x = 5?","explain":"y = kx^2; 36 = 9k so k = 4; when x = 5, y = 4 x 25 = 100.","type":"mcq","options":["60","80","100","225"],"answer":2},{"s":"Maths (Higher)","t":"direct & inverse proportion","q":"If y is inversely proportional to x, then doubling x halves y.","explain":"Inverse proportion means y = k/x; if x doubles, y becomes half.","type":"mcq","options":["True","False"],"answer":0},{"s":"Maths (Higher)","t":"direct & inverse proportion","q":"y is inversely proportional to x. When x = 4, y = 15. What is y when x = 12?","explain":"y = k/x; 15 = k/4 so k = 60; y = 60/12 = 5.","type":"numeric","answer":5,"tolerance":0},{"s":"Maths (Higher)","t":"fractions","q":"Calculate 3/4 + 2/5. Write your answer as a single improper fraction.","explain":"Common denominator 20: 15/20 + 8/20 = 23/20.","type":"short","accept":["23/20"]},{"s":"Maths (Higher)","t":"fractions","q":"Calculate 2/3 x 9/10. Give the result as a decimal.","explain":"2/3 x 9/10 = 18/30 = 3/5 = 0.6.","type":"numeric","answer":0.6,"tolerance":0},{"s":"Science (Higher)","t":"Biology: cell biology","q":"Which structure is found in plant cells but NOT in animal cells?","explain":"Plant cells have a cellulose cell wall; animal cells do not.","type":"mcq","options":["Mitochondria","Cell wall","Ribosome","Cell membrane"],"answer":1},{"s":"Science (Higher)","t":"Biology: cell biology","q":"Mitosis produces two genetically identical daughter cells.","explain":"Mitosis is used for growth and repair and produces identical copies.","type":"mcq","options":["True","False"],"answer":0},{"s":"Science (Higher)","t":"Biology: cell biology","q":"A cell has a diameter of 0.04 mm. What is this in micrometres (um)?","explain":"1 mm = 1000 um, so 0.04 mm x 1000 = 40 um.","type":"numeric","answer":40,"tolerance":0},{"s":"Science (Higher)","t":"Biology: enzymes","q":"What term describes an enzyme that has permanently lost its function due to high temperature?","explain":"High temperatures change the shape of the active site, denaturing the enzyme.","type":"mcq","options":["Inhibited","Denatured","Saturated","Activated"],"answer":1},{"s":"Science (Higher)","t":"Biology: enzymes","q":"What name is given to the specific region of an enzyme where the substrate binds?","explain":"The active site has a complementary shape to the substrate.","type":"short","accept":["active site"]},{"s":"Science (Higher)","t":"Photosynthesis","q":"Which two raw materials are used in photosynthesis?","explain":"Photosynthesis converts CO2 and water into glucose using light energy.","type":"mcq","options":["Oxygen and glucose","Carbon dioxide and water","Carbon dioxide and oxygen","Glucose and water"],"answer":1},{"s":"Science (Higher)","t":"Photosynthesis","q":"Increasing light intensity always increases the rate of photosynthesis regardless of other conditions.","explain":"Other factors such as CO2 concentration or temperature can become limiting factors.","type":"mcq","options":["True","False"],"answer":1},{"s":"Science (Higher)","t":"Photosynthesis","q":"What is the main product of photosynthesis (other than oxygen)?","explain":"Photosynthesis produces glucose and oxygen from CO2 and water.","type":"short","accept":["glucose"]},{"s":"Science (Higher)","t":"Respiration","q":"Which is the correct word equation for aerobic respiration?","explain":"Aerobic respiration uses oxygen to break down glucose, releasing energy, CO2 and water.","type":"mcq","options":["Glucose + carbon dioxide -> water + oxygen + energy","Glucose + oxygen -> carbon dioxide + water + energy","Carbon dioxide + water -> glucose + oxygen + energy","Glucose -> lactic acid + energy"],"answer":1},{"s":"Science (Higher)","t":"Respiration","q":"What is the product of anaerobic respiration in human muscle cells?","explain":"Human muscles produce lactic acid when oxygen is limited during intense exercise.","type":"short","accept":["lactic acid","lactate"]},{"s":"Science (Higher)","t":"Homeostasis","q":"Which organ detects changes in blood glucose concentration and releases insulin?","explain":"The pancreas monitors blood glucose and releases insulin or glucagon.","type":"mcq","options":["Liver","Kidney","Pancreas","Adrenal gland"],"answer":2},{"s":"Science (Higher)","t":"Homeostasis","q":"Insulin causes blood glucose levels to fall by stimulating cells to take up glucose.","explain":"Insulin promotes glucose uptake by body cells, lowering blood glucose.","type":"mcq","options":["True","False"],"answer":0},{"s":"Science (Higher)","t":"The nervous system","q":"In a reflex arc, what is the correct order of components?","explain":"A reflex arc passes from receptor through sensory, relay and motor neurones to the effector.","type":"mcq","options":["Receptor -> motor neurone -> relay neurone -> effector","Receptor -> sensory neurone -> relay neurone -> motor neurone -> effector","Receptor -> relay neurone -> sensory neurone -> effector","Receptor -> sensory neurone -> motor neurone -> effector"],"answer":1},{"s":"Science (Higher)","t":"The nervous system","q":"What is the name of the gap between two neurones where a chemical signal is transmitted?","explain":"Neurotransmitters diffuse across the synapse to carry the signal to the next neurone.","type":"short","accept":["synapse"]},{"s":"Science (Higher)","t":"Infection & response","q":"Which type of white blood cell produces antibodies?","explain":"Lymphocytes produce specific antibodies in response to antigens on pathogens.","type":"mcq","options":["Phagocyte","Lymphocyte","Red blood cell","Platelet"],"answer":1},{"s":"Science (Higher)","t":"Infection & response","q":"Antibiotics are effective treatments for viral infections.","explain":"Antibiotics target bacteria and have no effect on viruses.","type":"mcq","options":["True","False"],"answer":1},{"s":"Science (Higher)","t":"Inheritance & genetics","q":"A person has the genotype Bb where B (brown eyes) is dominant and b (blue eyes) is recessive. What is their eye colour?","explain":"The dominant allele B is expressed even when only one copy is present.","type":"mcq","options":["Blue eyes","Brown eyes","Green eyes","Cannot be determined"],"answer":1},{"s":"Science (Higher)","t":"Inheritance & genetics","q":"What name is given to an organism with two different alleles for a gene?","explain":"Heterozygous organisms carry one dominant and one recessive allele.","type":"short","accept":["heterozygous","heterozygote"]},{"s":"Science (Higher)","t":"Variation & evolution","q":"What is the main mechanism of evolution according to Darwin?","explain":"Darwin proposed that organisms with advantageous traits are more likely to survive and reproduce.","type":"mcq","options":["Genetic mutation only","Natural selection","Selective breeding","Cloning"],"answer":1},{"s":"Science (Higher)","t":"Ecology","q":"What term describes all the organisms of one species living in a habitat at the same time?","explain":"A population is a group of individuals of the same species in the same area.","type":"short","accept":["population"]},{"s":"Science (Higher)","t":"Ecology","q":"Energy is transferred with 100% efficiency between each trophic level in a food chain.","explain":"Much energy is lost as heat from respiration and in waste at each level (only about 10% passes on).","type":"mcq","options":["True","False"],"answer":1},{"s":"Science (Higher)","t":"Chemistry: atomic structure","q":"An atom of carbon-14 has 6 protons. How many neutrons does it contain?","explain":"Neutrons = mass number minus atomic number = 14 - 6 = 8.","type":"mcq","options":["6","8","14","20"],"answer":1},{"s":"Science (Higher)","t":"Chemistry: atomic structure","q":"What name is given to atoms of the same element that have different numbers of neutrons?","explain":"Isotopes have the same atomic number but different mass numbers.","type":"short","accept":["isotopes","isotope"]},{"s":"Science (Higher)","t":"Chemistry: bonding","q":"Which type of bonding involves the transfer of electrons from a metal atom to a non-metal atom?","explain":"Ionic bonding involves electron transfer, forming oppositely charged ions.","type":"mcq","options":["Covalent bonding","Metallic bonding","Ionic bonding","Hydrogen bonding"],"answer":2},{"s":"Science (Higher)","t":"Chemistry: bonding","q":"Simple molecular substances have low melting points because they have weak forces between molecules.","explain":"Weak intermolecular forces require little energy to overcome, giving low melting points.","type":"mcq","options":["True","False"],"answer":0},{"s":"Science (Higher)","t":"Quantitative chemistry","q":"Calculate the relative formula mass (Mr) of water, H2O. (H = 1, O = 16)","explain":"Mr of H2O = (2 x 1) + 16 = 18.","type":"numeric","answer":18,"tolerance":0},{"s":"Science (Higher)","t":"Quantitative chemistry","q":"How many moles of atoms are in 24 g of carbon? (Ar of C = 12)","explain":"Moles = mass / Ar = 24 / 12 = 2 moles.","type":"mcq","options":["0.5","1","2","12"],"answer":2},{"s":"Science (Higher)","t":"Quantitative chemistry","q":"What is the term for the percentage of the theoretical yield that is actually obtained in a reaction?","explain":"Percentage yield = (actual yield / theoretical yield) x 100.","type":"short","accept":["percentage yield","percent yield"]},{"s":"Science (Higher)","t":"Chemical changes","q":"What is produced at the cathode during the electrolysis of dilute sulfuric acid?","explain":"Hydrogen ions are reduced at the cathode: 2H+ + 2e- -> H2.","type":"mcq","options":["Oxygen","Chlorine","Hydrogen","Sulfur"],"answer":2},{"s":"Science (Higher)","t":"Chemical changes","q":"A neutralisation reaction between an acid and an alkali produces a salt and water.","explain":"Acid + alkali -> salt + water is the general equation for neutralisation.","type":"mcq","options":["True","False"],"answer":0},{"s":"Science (Higher)","t":"Rate of reaction","q":"Which of the following would NOT increase the rate of a chemical reaction?","explain":"Decreasing concentration reduces the frequency of collisions, lowering the rate.","type":"mcq","options":["Increasing temperature","Using a catalyst","Decreasing the concentration of reactants","Increasing surface area"],"answer":2},{"s":"Science (Higher)","t":"Rate of reaction","q":"What does a catalyst do to the activation energy of a reaction?","explain":"A catalyst provides an alternative pathway with a lower activation energy.","type":"short","accept":["decreases it","lowers it","reduces it","lowers","decreases","reduces"]},{"s":"Science (Higher)","t":"Organic chemistry","q":"What is the general formula for alkanes?","explain":"Alkanes are saturated hydrocarbons with the general formula CnH2n+2.","type":"mcq","options":["CnH2n","CnH2n+2","CnH2n-2","CnHn"],"answer":1},{"s":"Science (Higher)","t":"Organic chemistry","q":"What type of reaction do alkenes undergo with bromine water?","explain":"Alkenes have a C=C double bond and undergo addition reactions, decolourising bromine water.","type":"short","accept":["addition","addition reaction"]},{"s":"Science (Higher)","t":"The atmosphere","q":"Approximately what percentage of the Earth's atmosphere is nitrogen?","explain":"Nitrogen makes up about 78% of the atmosphere.","type":"numeric","answer":78,"tolerance":1},{"s":"Science (Higher)","t":"Using resources","q":"Which process is used to extract metals that are too reactive to be reduced by carbon?","explain":"Very reactive metals such as aluminium are extracted by electrolysis.","type":"mcq","options":["Displacement","Electrolysis","Smelting","Fractional distillation"],"answer":1},{"s":"Science (Higher)","t":"Physics: energy & forces","q":"A 2 kg object moves at 3 m/s. Calculate its kinetic energy in joules. (KE = 1/2 m v^2)","explain":"KE = 0.5 x 2 x 3^2 = 0.5 x 2 x 9 = 9 J.","type":"numeric","answer":9,"tolerance":0},{"s":"Science (Higher)","t":"Physics: energy & forces","q":"What is the name given to energy stored in a stretched spring?","explain":"Energy stored in a deformed elastic object is called elastic potential energy.","type":"short","accept":["elastic potential energy","elastic potential","elastic strain energy"]},{"s":"Science (Higher)","t":"Electricity","q":"A resistor has a potential difference of 12 V across it and a current of 3 A through it. What is its resistance?","explain":"R = V / I = 12 / 3 = 4 ohms (Ohm's law).","type":"mcq","options":["0.25 ohms","4 ohms","36 ohms","9 ohms"],"answer":1},{"s":"Science (Higher)","t":"Electricity","q":"In a series circuit, the current is the same at every point.","explain":"There is only one path for current in a series circuit, so current is identical throughout.","type":"mcq","options":["True","False"],"answer":0},{"s":"Science (Higher)","t":"Electricity","q":"A charge of 60 C passes a point in 20 s. What is the current in amperes? (I = Q / t)","explain":"I = Q / t = 60 / 20 = 3 A.","type":"numeric","answer":3,"tolerance":0},{"s":"Science (Higher)","t":"Particle model","q":"Which state of matter has a definite volume but no definite shape?","explain":"Liquids have a fixed volume but take the shape of their container.","type":"mcq","options":["Solid","Liquid","Gas","Plasma"],"answer":1},{"s":"Science (Higher)","t":"Particle model","q":"What is the name of the process by which a liquid changes into a gas below its boiling point?","explain":"Evaporation occurs at the surface when energetic particles escape the liquid.","type":"short","accept":["evaporation"]},{"s":"Science (Higher)","t":"Atomic structure & radioactivity","q":"Which type of radiation is most penetrating and requires lead or thick concrete to stop it?","explain":"Gamma radiation has no charge and very high penetrating power.","type":"mcq","options":["Alpha","Beta","Gamma","Neutron"],"answer":2},{"s":"Science (Higher)","t":"Atomic structure & radioactivity","q":"During beta decay, a neutron in the nucleus changes into a proton and a beta particle (electron) is emitted.","explain":"Beta decay converts a neutron to a proton, increasing the atomic number by 1.","type":"mcq","options":["True","False"],"answer":0},{"s":"Science (Higher)","t":"Atomic structure & radioactivity","q":"What term describes the time taken for the activity of a radioactive source to halve?","explain":"Half-life measures the rate of decay of a radioactive isotope.","type":"short","accept":["half-life","half life"]},{"s":"Science (Higher)","t":"Forces & motion","q":"A car accelerates from 0 m/s to 20 m/s in 4 s. What is its acceleration?","explain":"a = (v - u) / t = (20 - 0) / 4 = 5 m/s^2.","type":"mcq","options":["5 m/s^2","80 m/s^2","0.2 m/s^2","40 m/s^2"],"answer":0},{"s":"Science (Higher)","t":"Forces & motion","q":"A 1000 kg car accelerates at 2 m/s^2. What is the resultant force on it in newtons? (F = m x a)","explain":"F = m x a = 1000 x 2 = 2000 N.","type":"numeric","answer":2000,"tolerance":0},{"s":"Science (Higher)","t":"Waves","q":"What is the wave speed if a wave has a frequency of 50 Hz and a wavelength of 2 m?","explain":"Wave speed = frequency x wavelength = 50 x 2 = 100 m/s.","type":"mcq","options":["25 m/s","52 m/s","100 m/s","0.04 m/s"],"answer":2},{"s":"Science (Higher)","t":"Waves","q":"Is a sound wave transverse or longitudinal?","explain":"Sound waves are longitudinal; particle oscillations are parallel to the direction of travel.","type":"short","accept":["longitudinal"]},{"s":"Science (Higher)","t":"Magnetism & electromagnetism","q":"What is produced when a current-carrying conductor is placed in a magnetic field?","explain":"A current-carrying conductor in a magnetic field experiences a force: the motor effect.","type":"mcq","options":["Electromagnetic induction","The motor effect","The generator effect","The photoelectric effect"],"answer":1},{"s":"Science (Higher)","t":"Magnetism & electromagnetism","q":"A step-up transformer increases voltage and decreases current.","explain":"Step-up transformers have more turns on the secondary coil; voltage increases and current decreases to conserve power.","type":"mcq","options":["True","False"],"answer":0},{"s":"Business Studies","t":"Business in the real world","q":"Which of the following best describes an entrepreneur?","explain":"An entrepreneur organises resources, starts a business, and bears the financial risk.","type":"mcq","options":["A person who manages a large public company","A person who organises resources to set up a business and takes on financial risk","A person who invests in shares on the stock market","A person who works for a business and earns a wage"],"answer":1},{"s":"Business Studies","t":"Business in the real world","q":"A business that is owned by its members and shares profits among them is called a:","explain":"Co-operatives are owned and run by their members, who share in the profits.","type":"mcq","options":["Public limited company","Franchise","Co-operative","Sole trader"],"answer":2},{"s":"Business Studies","t":"Business in the real world","q":"A sole trader has unlimited liability, meaning the owner is personally responsible for all business debts.","explain":"Unlimited liability means personal assets can be used to cover business debts.","type":"mcq","options":["True","False"],"answer":0},{"s":"Business Studies","t":"Business in the real world","q":"Which type of business ownership offers limited liability to its owners?","explain":"A private limited company is a separate legal entity, so shareholders have limited liability.","type":"mcq","options":["Sole trader","Partnership (ordinary)","Private limited company (Ltd)","Market stall"],"answer":2},{"s":"Business Studies","t":"Business in the real world","q":"What term describes the protection that means shareholders can only lose the amount they invested?","explain":"Limited liability caps a shareholder's loss at the value of their investment.","type":"short","accept":["limited liability"]},{"s":"Business Studies","t":"Business in the real world","q":"Maximising profit is most associated with which type of organisation?","explain":"Private sector businesses are primarily driven by the profit motive.","type":"mcq","options":["Charity","Public sector organisation","Private sector business","Co-operative"],"answer":2},{"s":"Business Studies","t":"Business in the real world","q":"A franchisee starts a completely new, independent brand of their own.","explain":"A franchisee pays to use an established brand and business model owned by the franchisor.","type":"mcq","options":["True","False"],"answer":1},{"s":"Business Studies","t":"Influences on business","q":"Which of the following is an external stakeholder of a business?","explain":"External stakeholders are not part of the business but are affected by it, such as local residents.","type":"mcq","options":["A production worker","The finance manager","A local resident affected by the business","A shareholder on the board"],"answer":2},{"s":"Business Studies","t":"Influences on business","q":"An increase in interest rates reduces the cost of borrowing for businesses.","explain":"Higher interest rates increase the cost of borrowing and loan repayments.","type":"mcq","options":["True","False"],"answer":1},{"s":"Business Studies","t":"Influences on business","q":"During a recession, consumer spending typically:","explain":"Recessions cause falling incomes and confidence, reducing spending.","type":"mcq","options":["Increases significantly","Stays exactly the same","Falls as incomes and confidence decline","Rises because prices are lower"],"answer":2},{"s":"Business Studies","t":"Influences on business","q":"What tax is charged on the profit of a limited company in the UK?","explain":"Corporation tax is levied on company profits.","type":"short","accept":["corporation tax"]},{"s":"Business Studies","t":"Influences on business","q":"What is the main risk of sourcing cheaper components from distant overseas suppliers?","explain":"Relying on distant suppliers increases vulnerability to delays and disruption.","type":"mcq","options":["Increased domestic competition","Supply chain disruption due to distance and reliance on suppliers","Higher corporation tax","Reduced product range"],"answer":1},{"s":"Business Studies","t":"Influences on business","q":"Ethical businesses may accept lower short-term profits in order to behave responsibly.","explain":"Acting ethically can raise costs short term but build long-term reputation.","type":"mcq","options":["True","False"],"answer":0},{"s":"Business Studies","t":"Influences on business","q":"Which is an example of a business acting in an environmentally responsible way?","explain":"Switching to renewable energy reduces carbon emissions.","type":"mcq","options":["Dumping waste in a river to cut costs","Switching to renewable energy in its factories","Lobbying to reduce environmental rules","Increasing packaging"],"answer":1},{"s":"Business Studies","t":"Business operations","q":"Which production method is most suitable for making a one-off, bespoke item to a customer's exact specification?","explain":"Job production creates a single unique item tailored to the customer.","type":"mcq","options":["Flow production","Batch production","Job production","Mass production"],"answer":2},{"s":"Business Studies","t":"Business operations","q":"Just-In-Time (JIT) means holding large quantities of stock to avoid running out.","explain":"JIT minimises stock by ordering materials only when needed, reducing storage costs.","type":"mcq","options":["True","False"],"answer":1},{"s":"Business Studies","t":"Business operations","q":"A key benefit of Just-In-Time (JIT) production is:","explain":"JIT reduces the need for warehousing and lowers the cost of holding stock.","type":"mcq","options":["Always having surplus stock","Reduced storage and holding costs","Longer production lead times","Less dependence on suppliers"],"answer":1},{"s":"Business Studies","t":"Business operations","q":"What term describes checking that goods meet a required standard before reaching the customer?","explain":"Quality control inspects output to catch defects before products reach customers.","type":"short","accept":["quality control","quality assurance"]},{"s":"Business Studies","t":"Business operations","q":"Flow production is best suited to which type of output?","explain":"Flow production uses a continuous line, ideal for large volumes of identical products.","type":"mcq","options":["Bespoke furniture made to order","Small batches of different cakes","Continuous high-volume identical products like canned drinks","Prototype designs"],"answer":2},{"s":"Business Studies","t":"Human resources","q":"Which of the following is an example of off-the-job training?","explain":"Off-the-job training takes place away from the workplace, such as at a college.","type":"mcq","options":["Shadowing a colleague on the shop floor","Attending an external college course","Learning by doing a task under supervision","Reading the induction handbook at your desk"],"answer":1},{"s":"Business Studies","t":"Human resources","q":"A tall organisational structure has many layers of hierarchy, which can slow communication.","explain":"Each extra layer increases the chance of delay and distortion of messages.","type":"mcq","options":["True","False"],"answer":0},{"s":"Business Studies","t":"Human resources","q":"According to Herzberg, which of the following is a motivator (not a hygiene factor)?","explain":"Herzberg identified achievement and recognition as true motivators.","type":"mcq","options":["Company policy","Salary","Achievement and recognition","Working conditions"],"answer":2},{"s":"Business Studies","t":"Human resources","q":"What term describes the number of employees directly managed by one manager?","explain":"Span of control is the number of subordinates reporting directly to a manager.","type":"short","accept":["span of control"]},{"s":"Business Studies","t":"Human resources","q":"Internal recruitment means:","explain":"Internal recruitment fills roles from the existing workforce.","type":"mcq","options":["Hiring from a recruitment agency","Filling a vacancy by promoting or moving an existing employee","Advertising on an external website","Using a headhunter"],"answer":1},{"s":"Business Studies","t":"Human resources","q":"Which theorist introduced the hierarchy of needs?","explain":"Maslow's hierarchy ranks needs from physiological at the base to self-actualisation at the top.","type":"mcq","options":["Frederick Taylor","Elton Mayo","Abraham Maslow","Frederick Herzberg"],"answer":2},{"s":"Business Studies","t":"Marketing","q":"Which type of market research collects new data directly from consumers for the first time?","explain":"Primary research gathers new, original data directly from the target market.","type":"mcq","options":["Secondary research","Desk research","Primary research","Published research"],"answer":2},{"s":"Business Studies","t":"Marketing","q":"Market segmentation involves dividing the market into groups of consumers with similar characteristics.","explain":"Segmentation lets businesses target different groups with tailored marketing.","type":"mcq","options":["True","False"],"answer":0},{"s":"Business Studies","t":"Marketing","q":"Charging a high initial price for a new innovative product before gradually reducing it is called:","explain":"Price skimming captures revenue from early adopters before lowering prices.","type":"mcq","options":["Penetration pricing","Competitive pricing","Price skimming","Cost-plus pricing"],"answer":2},{"s":"Business Studies","t":"Marketing","q":"Which element of the marketing mix refers to the channels used to get a product to the consumer?","explain":"Place covers distribution channels such as shops, websites or delivery.","type":"mcq","options":["Product","Price","Place","Promotion"],"answer":2},{"s":"Business Studies","t":"Marketing","q":"What term describes setting a price just below a round number (e.g. 9.99 instead of 10.00)?","explain":"Psychological pricing exploits the perception that 9.99 seems much cheaper than 10.00.","type":"short","accept":["psychological pricing","psychological"]},{"s":"Business Studies","t":"Marketing","q":"Which of the following is an example of above-the-line promotion?","explain":"Above-the-line promotion uses mass media such as TV to reach a wide audience.","type":"mcq","options":["A loyalty card scheme","A television advertisement","A salesperson visiting a customer","A money-off coupon"],"answer":1},{"s":"Business Studies","t":"Finance","q":"A business sells 500 units at a price of 12 each. What is the total revenue in pounds?","explain":"Total revenue = price x quantity = 12 x 500 = 6000.","type":"numeric","answer":6000,"tolerance":0},{"s":"Business Studies","t":"Finance","q":"A business has total revenue of 45000 and total costs of 32000. What is the profit in pounds?","explain":"Profit = total revenue - total costs = 45000 - 32000 = 13000.","type":"numeric","answer":13000,"tolerance":0},{"s":"Business Studies","t":"Finance","q":"A product sells for 20. Variable cost per unit is 8 and fixed costs are 3600. What is the break-even quantity in units?","explain":"Break-even = fixed costs / (price - variable cost) = 3600 / (20 - 8) = 300 units.","type":"numeric","answer":300,"tolerance":0},{"s":"Business Studies","t":"Finance","q":"Revenue last year was 80000. Revenue this year is 92000. What is the percentage change in revenue?","explain":"Percentage change = ((92000 - 80000) / 80000) x 100 = 15%.","type":"numeric","answer":15,"tolerance":0},{"s":"Business Studies","t":"Finance","q":"Which of the following is a source of external finance for a new small business?","explain":"A bank loan comes from outside the business, unlike retained profit or savings.","type":"mcq","options":["Retained profit","Selling unwanted assets","A bank loan","Owner's personal savings"],"answer":2},{"s":"Business Studies","t":"Finance","q":"A cash flow forecast shows the expected movement of cash into and out of a business over a future period.","explain":"It helps a business predict when it may run short of cash.","type":"mcq","options":["True","False"],"answer":0},{"s":"Business Studies","t":"Finance","q":"Which of the following would improve a business's cash flow in the short term?","explain":"Chasing debtors speeds up cash inflows, improving the cash position.","type":"mcq","options":["Buying more machinery on credit","Giving customers longer to pay","Chasing debtors to pay sooner","Increasing stock levels"],"answer":2},{"s":"Business Studies","t":"Finance","q":"What name is given to costs that stay the same regardless of how many units are produced, such as rent?","explain":"Fixed costs do not vary with output in the short run.","type":"short","accept":["fixed costs","fixed cost"]},{"s":"Business Studies","t":"Finance","q":"Fixed costs are 5000, variable cost per unit is 6, and each unit sells for 16. If 700 units are sold, what is the profit in pounds?","explain":"Revenue = 11200; total cost = 5000 + 4200 = 9200; profit = 11200 - 9200 = 2000.","type":"numeric","answer":2000,"tolerance":0},{"s":"Business Studies","t":"Finance","q":"A profit and loss account (income statement) shows:","explain":"The income statement summarises trading performance over a period.","type":"mcq","options":["What the business owns and owes at a point in time","The cash moving in and out each week","Revenue, costs, and profit or loss over a period","The number of units sold each month"],"answer":2},{"s":"Business Studies","t":"Finance","q":"A business can be profitable yet still have cash flow problems if customers take too long to pay.","explain":"Profit is an accounting measure; cash problems arise when inflows do not arrive in time.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Types of data","q":"Which of the following is an example of continuous data?","explain":"Continuous data can take any value in a range; height is measured on a continuous scale.","type":"mcq","options":["Number of siblings","Shoe size (UK whole sizes)","Height of a plant in cm","Favourite colour"],"answer":2},{"s":"Statistics","t":"Types of data","q":"The number of goals scored in a football match is best described as:","explain":"Goals can only be whole numbers, making this discrete quantitative data.","type":"mcq","options":["Continuous quantitative","Discrete quantitative","Ordinal qualitative","Nominal qualitative"],"answer":1},{"s":"Statistics","t":"Types of data","q":"Ordinal data can be placed in a meaningful order but the gaps between values are not necessarily equal.","explain":"Ordinal data has rank order but intervals between ranks are not guaranteed equal.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Sampling methods","q":"A researcher numbers every student 1-300 and uses a random number generator to pick 30. This is:","explain":"Every member is numbered and selections are made entirely at random.","type":"mcq","options":["Stratified sampling","Systematic sampling","Simple random sampling","Quota sampling"],"answer":2},{"s":"Statistics","t":"Sampling methods","q":"A school has 200 boys and 100 girls. A stratified sample of 60 is needed. How many girls should be in the sample?","explain":"Girls are 100/300 of the population; 100/300 x 60 = 20.","type":"mcq","options":["10","20","30","40"],"answer":1},{"s":"Statistics","t":"Sampling methods","q":"In systematic sampling you choose every nth item from a list after a random start.","explain":"Systematic sampling selects every nth member after a random starting point.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Sampling methods","q":"Give one advantage of a stratified sample over a simple random sample.","explain":"Stratified sampling ensures key subgroups appear in the correct proportions.","type":"short","accept":["more representative","represents subgroups","proportional representation","represents each group"]},{"s":"Statistics","t":"The data collection process","q":"A survey asks 'How many hours of TV do you watch?' with boxes: 0-2, 2-4, 4-6. What is wrong with this?","explain":"A value of exactly 2 or 4 could go in two categories, so intervals must not overlap.","type":"mcq","options":["The question is biased","The response categories overlap","There are too few categories","The question is leading"],"answer":1},{"s":"Statistics","t":"The data collection process","q":"Primary data is data that has been collected by someone else for a different purpose.","explain":"Primary data is collected first-hand by the researcher; secondary data is collected by others.","type":"mcq","options":["True","False"],"answer":1},{"s":"Statistics","t":"The Statistical Enquiry Cycle","q":"Which is the correct order for the Statistical Enquiry Cycle?","explain":"The cycle runs: plan, collect data, process and represent, then interpret.","type":"mcq","options":["Collect, Plan, Analyse, Interpret","Plan, Collect, Process & represent, Interpret","Interpret, Plan, Collect, Analyse","Plan, Interpret, Collect, Represent"],"answer":1},{"s":"Statistics","t":"Averages & spread","q":"Find the mean of: 3, 7, 8, 10, 12.","explain":"Sum = 40; divide by 5 values gives mean = 8.","type":"numeric","answer":8,"tolerance":0},{"s":"Statistics","t":"Averages & spread","q":"Find the median of: 5, 1, 9, 3, 7, 2, 8.","explain":"Ordered: 1,2,3,5,7,8,9 - the middle (4th) value is 5.","type":"numeric","answer":5,"tolerance":0},{"s":"Statistics","t":"Averages & spread","q":"Find the range of: 14, 3, 27, 9, 21.","explain":"Range = highest - lowest = 27 - 3 = 24.","type":"numeric","answer":24,"tolerance":0},{"s":"Statistics","t":"Averages & spread","q":"The ages of five people are 12, 15, 15, 18, 20. Which average equals 15?","explain":"Middle value = 15 (median); 15 appears twice (mode); mean = 80/5 = 16.","type":"mcq","options":["Mean only","Median only","Mode only","Both median and mode"],"answer":3},{"s":"Statistics","t":"Averages & spread","q":"A frequency table shows scores 1, 2, 3 with frequencies 4, 5, 1. Calculate the mean score.","explain":"(1x4 + 2x5 + 3x1) / 10 = 17/10 = 1.7.","type":"numeric","answer":1.7,"tolerance":0.05},{"s":"Statistics","t":"Quartiles & IQR","q":"The lower quartile of a data set is 12 and the upper quartile is 30. What is the interquartile range?","explain":"IQR = UQ - LQ = 30 - 12 = 18.","type":"numeric","answer":18,"tolerance":0},{"s":"Statistics","t":"Quartiles & IQR","q":"The interquartile range is a better measure of spread than the range when there are outliers.","explain":"IQR ignores the extreme 25% at each end, so outliers do not distort it.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Standard deviation","q":"Two classes both have a mean score of 60. Class A has a standard deviation of 5 and Class B of 15. What does this tell us?","explain":"A smaller standard deviation means scores are clustered more closely around the mean.","type":"mcq","options":["Class A scored higher on average","Class B has more consistent scores","Class A has more consistent scores","Both have identical spread"],"answer":2},{"s":"Statistics","t":"Standard deviation","q":"Standard deviation can never be a negative number.","explain":"Standard deviation is a square root of a mean of squares, so it is always >= 0.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Cumulative frequency & box plots","q":"On a cumulative frequency graph for 80 values, at which cumulative frequency is the median read off?","explain":"The median corresponds to the n/2 = 40th value.","type":"mcq","options":["20","40","60","80"],"answer":1},{"s":"Statistics","t":"Cumulative frequency & box plots","q":"Name the five values needed to draw a box plot.","explain":"A box plot needs the five-number summary: minimum, Q1, median, Q3, maximum.","type":"short","accept":["minimum, lower quartile, median, upper quartile, maximum","min, q1, median, q3, max","minimum lower quartile median upper quartile maximum"]},{"s":"Statistics","t":"Cumulative frequency & box plots","q":"A longer box in a box plot indicates a larger interquartile range.","explain":"The box spans Q1 to Q3, so a wider box means a larger IQR.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Histograms & frequency density","q":"In a histogram, what does the AREA of each bar represent?","explain":"Area = frequency density x class width = frequency.","type":"mcq","options":["Frequency density","Class width","Frequency","Relative frequency"],"answer":2},{"s":"Statistics","t":"Histograms & frequency density","q":"A class interval of width 5 has a frequency of 30. What is the frequency density?","explain":"Frequency density = frequency / class width = 30 / 5 = 6.","type":"numeric","answer":6,"tolerance":0},{"s":"Statistics","t":"Histograms & frequency density","q":"A bar on a histogram has frequency density 4 and class width 10. What is the frequency for that class?","explain":"Frequency = frequency density x class width = 4 x 10 = 40.","type":"numeric","answer":40,"tolerance":0},{"s":"Statistics","t":"Scatter graphs & correlation","q":"As revision hours increase, exam scores also increase. This describes:","explain":"When both variables increase together the relationship is positive correlation.","type":"mcq","options":["Negative correlation","No correlation","Positive correlation","Causation only"],"answer":2},{"s":"Statistics","t":"Scatter graphs & correlation","q":"Correlation between two variables proves that one variable causes the other.","explain":"Correlation shows association, not causation.","type":"mcq","options":["True","False"],"answer":1},{"s":"Statistics","t":"Scatter graphs & correlation","q":"What is the purpose of a line of best fit on a scatter graph?","explain":"A line of best fit summarises the trend and allows predictions within the data range.","type":"short","accept":["to show the trend","to make predictions","to show correlation","to predict values","trend"]},{"s":"Statistics","t":"Time series & moving averages","q":"Sales for four quarters are 10, 14, 8, 12. What is the 4-point moving average of these values?","explain":"Moving average = (10+14+8+12)/4 = 44/4 = 11.","type":"mcq","options":["10","11","12","13"],"answer":1},{"s":"Statistics","t":"Time series & moving averages","q":"A moving average is used to smooth out seasonal variation in a time series.","explain":"Averaging over a full cycle removes seasonal fluctuations and reveals the trend.","type":"mcq","options":["True","False"],"answer":0},{"s":"Statistics","t":"Index numbers","q":"The price of an item was 80p in the base year and is now 100p. Calculate the index number (base year = 100).","explain":"Index = (current / base) x 100 = (100/80) x 100 = 125.","type":"numeric","answer":125,"tolerance":0},{"s":"Statistics","t":"Index numbers","q":"An index number of 92 compared with a base of 100 means the value has:","explain":"An index of 92 is 8 below the base of 100, an 8% decrease.","type":"mcq","options":["Increased by 92%","Decreased by 8%","Increased by 8%","Decreased by 92%"],"answer":1},{"s":"Statistics","t":"Probability","q":"A bag contains 3 red and 7 blue counters. What is the probability a random counter is red? Give a decimal.","explain":"P(red) = 3/10 = 0.3.","type":"numeric","answer":0.3,"tolerance":0.001},{"s":"Statistics","t":"Probability","q":"A biased coin has P(heads) = 0.6. The coin is flipped 200 times. What is the expected number of heads?","explain":"Expected frequency = probability x trials = 0.6 x 200 = 120.","type":"numeric","answer":120,"tolerance":0},{"s":"Statistics","t":"Probability","q":"A bag has 4 red and 6 green balls. One is taken (not replaced), then a second. What is P(both red)?","explain":"P(red then red) = (4/10) x (3/9) = 12/90 = 2/15.","type":"mcq","options":["4/25","2/15","4/15","16/100"],"answer":1},{"s":"Statistics","t":"Probability","q":"If two events are mutually exclusive, P(A or B) = P(A) + P(B).","explain":"Mutually exclusive events cannot both occur, so probabilities add.","type":"mcq","options":["True","False"],"answer":0},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"How do you say 'my older brother' in Spanish?","explain":"hermano = brother, mayor = older for family members.","type":"short","accept":["mi hermano mayor"]},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"What does 'Me llevo bien con mi madre' mean?","explain":"Llevarse bien con = to get on well with.","type":"mcq","options":["I live with my mother","I get on well with my mother","I argue with my mother","I miss my mother"],"answer":1},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"How do you say 'I am hungry' in Spanish? (Use tener)","explain":"Hunger is expressed with tener: tener hambre = to be hungry.","type":"short","accept":["tengo hambre"]},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"Which sentence correctly uses estar?","explain":"Estar is used for temporary states like tiredness; professions and characteristics use ser.","type":"mcq","options":["Yo estoy profesora","Mi hermana está cansada","Él está médico","Nosotros estamos altos"],"answer":1},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"The Spanish word 'delgado/a' means 'tall'.","explain":"Delgado/a means thin/slim; alto/a means tall.","type":"mcq","options":["True","False"],"answer":1},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"Translate into Spanish: 'I wake up at seven o'clock.'","explain":"Despertarse is reflexive; yo form is me despierto.","type":"short","accept":["me despierto a las siete"]},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"What does 'saludable' mean?","explain":"Saludable = healthy.","type":"mcq","options":["delicious","healthy","filling","cheap"],"answer":1},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"Which is the correct preterite (yo) form of 'comer'?","explain":"Regular -er verbs in the preterite yo form end in -í: comí.","type":"mcq","options":["comí","comé","comer","comía"],"answer":0},{"s":"Spanish","t":"Theme 1: People & lifestyle","q":"Translate: 'When I was young, I used to play in the park.'","explain":"Habitual past actions use the imperfect: era, jugaba.","type":"mcq","options":["Cuando era joven, jugaba en el parque.","Cuando era joven, jugué en el parque.","Cuando soy joven, juego en el parque.","Cuando fui joven, jugaré en el parque."],"answer":0},{"s":"Spanish","t":"School & education","q":"How do you say 'I study Spanish and science' in Spanish?","explain":"Estudiar = to study; yo form = estudio.","type":"short","accept":["estudio español y ciencias","estudio espanol y ciencias"]},{"s":"Spanish","t":"School & education","q":"What does 'el horario' mean?","explain":"El horario = the timetable.","type":"mcq","options":["the homework","the uniform","the timetable","the classroom"],"answer":2},{"s":"Spanish","t":"School & education","q":"'Los deberes' means 'the teachers' in Spanish.","explain":"Los deberes = homework; los profesores = the teachers.","type":"mcq","options":["True","False"],"answer":1},{"s":"Spanish","t":"School & education","q":"Which word means 'boring' when describing a school subject?","explain":"Aburrido/a = boring; divertido = fun; difícil = difficult; útil = useful.","type":"mcq","options":["aburrido","divertido","difícil","útil"],"answer":0},{"s":"Spanish","t":"Theme 2: Popular culture","q":"How do you say 'I like listening to music' in Spanish?","explain":"Gustar + infinitive: me gusta escuchar música.","type":"short","accept":["me gusta escuchar música","me gusta escuchar musica"]},{"s":"Spanish","t":"Theme 2: Popular culture","q":"What does 'Suelo ir al cine los fines de semana' mean?","explain":"Soler + infinitive expresses a habitual action: I usually go.","type":"mcq","options":["I went to the cinema last weekend","I usually go to the cinema at weekends","I want to go to the cinema this weekend","I will go to the cinema at weekends"],"answer":1},{"s":"Spanish","t":"Theme 2: Popular culture","q":"How do you say 'last Saturday' in Spanish?","explain":"El + day + pasado = last (day).","type":"short","accept":["el sábado pasado","el sabado pasado"]},{"s":"Spanish","t":"Theme 2: Popular culture","q":"Which option correctly translates 'I played football yesterday'?","explain":"Ayer requires the preterite; jugar is irregular: jugué.","type":"mcq","options":["Juego al fútbol ayer","Jugué al fútbol ayer","Jugaba al fútbol ayer","Voy a jugar al fútbol ayer"],"answer":1},{"s":"Spanish","t":"Theme 2: Popular culture","q":"'Prefiero' is the yo form of 'preferir' in the present tense.","explain":"Preferir is e→ie stem-changing; yo form = prefiero.","type":"mcq","options":["True","False"],"answer":0},{"s":"Spanish","t":"Theme 2: Popular culture","q":"What does 'una película de terror' mean?","explain":"Una película de terror = a horror film.","type":"mcq","options":["a comedy film","a horror film","a documentary","an action film"],"answer":1},{"s":"Spanish","t":"Theme 3: Communication & the world","q":"How do you say 'the environment' in Spanish?","explain":"Medio ambiente is the standard term for the environment.","type":"short","accept":["el medio ambiente","medio ambiente"]},{"s":"Spanish","t":"Theme 3: Communication & the world","q":"What does 'el reciclaje' mean?","explain":"El reciclaje = recycling.","type":"mcq","options":["pollution","recycling","renewable energy","deforestation"],"answer":1},{"s":"Spanish","t":"Theme 3: Communication & the world","q":"'Hace calor' is the correct way to say 'It is hot' (weather) in Spanish.","explain":"Weather uses hacer: hace calor = it is hot.","type":"mcq","options":["True","False"],"answer":0},{"s":"Spanish","t":"Theme 3: Communication & the world","q":"Translate into Spanish: 'I would like to travel to Spain.'","explain":"Me gustaría + infinitive expresses I would like to.","type":"short","accept":["me gustaría viajar a España","me gustaria viajar a espana"]},{"s":"Spanish","t":"Theme 3: Communication & the world","q":"Which word means 'to protect' in Spanish?","explain":"Proteger = to protect; contaminar = to pollute.","type":"mcq","options":["destruir","proteger","contaminar","desperdiciar"],"answer":1},{"s":"Spanish","t":"Town & transport","q":"What does 'Gira a la izquierda en el semáforo' mean?","explain":"Girar = to turn; izquierda = left; semáforo = traffic lights.","type":"mcq","options":["Turn right at the roundabout","Turn left at the traffic lights","Go straight on at the crossroads","Turn right at the bridge"],"answer":1},{"s":"Spanish","t":"Town & transport","q":"How do you say 'the train station' in Spanish?","explain":"Estación = station; de tren = of train.","type":"short","accept":["la estación de tren","la estacion de tren","la estación de trenes"]},{"s":"Spanish","t":"Town & transport","q":"'El centro comercial' means 'the town centre'.","explain":"Centro comercial = shopping centre; el centro = the town centre.","type":"mcq","options":["True","False"],"answer":1},{"s":"Spanish","t":"Jobs & future plans","q":"Translate: 'In the future I am going to study medicine.'","explain":"Near future = ir a + infinitive; voy a estudiar = I am going to study.","type":"short","accept":["en el futuro voy a estudiar medicina"]},{"s":"Spanish","t":"Jobs & future plans","q":"What does 'quisiera ser enfermero/a' mean?","explain":"Quisiera is used as a polite conditional: I would like.","type":"mcq","options":["I want to be a nurse","I would like to be a nurse","I am going to be a nurse","I was a nurse"],"answer":1},{"s":"Spanish","t":"Jobs & future plans","q":"Which sentence uses the conditional tense correctly?","explain":"Trabajaría = I would work; the conditional is for hypothetical situations.","type":"mcq","options":["Trabajaré en una oficina mañana","Trabajaba en una oficina de niño","Trabajaría en una oficina si pudiera","Trabajo en una oficina ahora"],"answer":2},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"Which is the correct imperfect tense (yo) form of 'vivir'?","explain":"-ir verbs in the imperfect yo form end in -ía: vivía.","type":"mcq","options":["viví","vivo","vivía","viviré"],"answer":2},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"'Fui' is the preterite yo form of both 'ser' (to be) and 'ir' (to go).","explain":"Ser and ir share identical preterite forms; context tells them apart.","type":"mcq","options":["True","False"],"answer":0},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"What is the near future (yo) of 'hacer'?","explain":"Near future = ir a + infinitive: voy a hacer.","type":"mcq","options":["haré","hago","haría","voy a hacer"],"answer":3},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"Give the present tense yo form of 'poder'.","explain":"Poder is o→ue stem-changing; yo = puedo.","type":"short","accept":["puedo"]},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"Which connective introduces a contrasting opinion in Spanish?","explain":"Sin embargo = however; además = furthermore; por eso = therefore.","type":"mcq","options":["además","también","sin embargo","por eso"],"answer":2},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"How do you say 'I think that it is important' in Spanish?","explain":"Creer que + opinion is a standard opinion phrase.","type":"short","accept":["creo que es importante"]},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"What does the question word '¿Cuánto/a?' mean?","explain":"¿Cuánto/a? = How much?; ¿Cuántos/as? = How many?","type":"mcq","options":["Where?","When?","How much/many?","Why?"],"answer":2},{"s":"Spanish","t":"Grammar: tenses & opinions","q":"The correct preterite (él/ella) form of 'hablar' is 'habló'.","explain":"Regular -ar verbs in the preterite él/ella form add -ó: habló.","type":"mcq","options":["True","False"],"answer":0},{"s":"Spanish","t":"Numbers & dates","q":"How do you say 'the fifteenth of March' in Spanish?","explain":"Dates use cardinal numbers (quince = 15), except el primero for the 1st.","type":"mcq","options":["el quince de marzo","el quinto de marzo","el quinceavo de marzo","el decimoquinto de marzo"],"answer":0},{"s":"Spanish","t":"Numbers & dates","q":"What is the Spanish word for the number 80?","explain":"Ochenta = 80.","type":"short","accept":["ochenta"]},{"s":"Geography","t":"Natural hazards: tectonics","q":"Which type of plate boundary is associated with the formation of fold mountains?","explain":"At destructive boundaries, compression folds and uplifts rock into mountain ranges.","type":"mcq","options":["Divergent boundary","Constructive boundary","Conservative boundary","Destructive boundary"],"answer":3},{"s":"Geography","t":"Natural hazards: tectonics","q":"Earthquakes can occur at all three types of plate boundary.","explain":"Tectonic movement at constructive, destructive and conservative boundaries all generate earthquakes.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Natural hazards: tectonics","q":"What is the name given to the point on Earth's surface directly above the focus of an earthquake?","explain":"The epicentre is the surface point directly above the underground focus.","type":"mcq","options":["Epicentre","Fault line","Seismic zone","Focus"],"answer":0},{"s":"Geography","t":"Natural hazards: tectonics","q":"Name the scale commonly used to measure the magnitude of an earthquake.","explain":"The Richter scale measures the energy released by an earthquake.","type":"short","accept":["Richter scale","moment magnitude scale","Richter"]},{"s":"Geography","t":"Natural hazards: tectonics","q":"Which of the following is a PRIMARY effect of a volcanic eruption?","explain":"Primary effects occur directly from the eruption; lava flows destroy structures immediately.","type":"mcq","options":["Disease outbreaks","Lava flows destroying buildings","Disruption to tourism","Homelessness due to evacuation"],"answer":1},{"s":"Geography","t":"Weather hazards & tropical storms","q":"Between which latitudes do tropical storms typically form?","explain":"Tropical storms need sea temperatures above 27 C and the Coriolis effect, found between 5 and 30 degrees.","type":"mcq","options":["0 to 5 degrees","5 to 30 degrees","30 to 50 degrees","50 to 70 degrees"],"answer":1},{"s":"Geography","t":"Weather hazards & tropical storms","q":"Tropical storms lose energy and weaken when they move over land.","explain":"They are fuelled by warm ocean water; over land they lose their energy source.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Weather hazards & tropical storms","q":"What is the term for the calm, cloud-free centre of a tropical storm?","explain":"The eye is a zone of low pressure and clear skies at the centre.","type":"short","accept":["eye","the eye"]},{"s":"Geography","t":"Weather hazards & tropical storms","q":"Which hazard is caused DIRECTLY by a tropical storm making landfall?","explain":"A storm surge is a rise in sea level driven by low pressure and strong winds.","type":"mcq","options":["Drought","Storm surge","Frost","Heatwave"],"answer":1},{"s":"Geography","t":"Weather hazards & tropical storms","q":"The UK receives most of its extreme weather from which system?","explain":"The UK is dominated by Atlantic depressions bringing wind and heavy rain.","type":"mcq","options":["Anticyclones moving east","Tropical cyclones crossing the Atlantic","Depressions tracking in from the west","Jet stream blocking over Scandinavia"],"answer":2},{"s":"Geography","t":"Climate change","q":"Which gas is the most significant human-produced contributor to current climate change?","explain":"Carbon dioxide from burning fossil fuels is the largest human-produced greenhouse gas.","type":"mcq","options":["Methane","Nitrous oxide","Carbon dioxide","Water vapour"],"answer":2},{"s":"Geography","t":"Climate change","q":"Milankovitch cycles are a natural cause of climate change.","explain":"They describe variations in Earth's orbit and tilt that alter solar radiation received.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Climate change","q":"What term describes strategies that adapt to the impacts of climate change rather than reducing its causes?","explain":"Adaptation adjusts to effects (e.g. flood defences); mitigation reduces emissions.","type":"short","accept":["adaptation"]},{"s":"Geography","t":"Climate change","q":"Which of the following is an example of MITIGATION of climate change?","explain":"Wind turbines generate electricity without emitting greenhouse gases, reducing the causes.","type":"mcq","options":["Building sea walls","Switching crops to drought-resistant varieties","Generating electricity from wind turbines","Creating emergency water reservoirs"],"answer":2},{"s":"Geography","t":"The living world: ecosystems","q":"What term describes all the living organisms and non-living components interacting in an area?","explain":"An ecosystem includes all biotic and abiotic components and their interactions.","type":"mcq","options":["Habitat","Biome","Ecosystem","Community"],"answer":2},{"s":"Geography","t":"The living world: ecosystems","q":"In a food chain, energy is transferred with 100% efficiency from one trophic level to the next.","explain":"Only about 10% is passed on; the rest is lost as heat and waste.","type":"mcq","options":["True","False"],"answer":1},{"s":"Geography","t":"Tropical rainforests","q":"In a tropical rainforest, where is most of the nutrient store found?","explain":"Rapid decomposition cycles nutrients quickly into plants, so most are held in the biomass.","type":"mcq","options":["Deep in the soil profile","In the leaf litter layer","Within the living biomass of plants","Dissolved in rivers"],"answer":2},{"s":"Geography","t":"Tropical rainforests","q":"Name the process by which rainforest trees release water vapour, helping maintain rainfall.","explain":"Transpiration releases water vapour which condenses to form rain.","type":"short","accept":["transpiration","evapotranspiration"]},{"s":"Geography","t":"Tropical rainforests","q":"Which of the following is NOT a direct cause of tropical rainforest deforestation?","explain":"Rising sea levels are a consequence of climate change, not a direct driver of deforestation.","type":"mcq","options":["Commercial logging","Subsistence farming","Rising sea levels","Cattle ranching"],"answer":2},{"s":"Geography","t":"Hot deserts & cold environments","q":"What is the maximum average annual precipitation used to define a hot desert climate?","explain":"Hot deserts receive less than 250 mm of rainfall per year.","type":"mcq","options":["100 mm","250 mm","500 mm","750 mm"],"answer":1},{"s":"Geography","t":"Hot deserts & cold environments","q":"Permafrost is a permanent feature of tundra environments.","explain":"Permafrost is ground frozen for at least two consecutive years, underlying most tundra.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Hot deserts & cold environments","q":"What term describes the spread of desert conditions into previously non-desert areas?","explain":"Desertification is land in semi-arid regions becoming increasingly arid and degraded.","type":"short","accept":["desertification"]},{"s":"Geography","t":"Hot deserts & cold environments","q":"Which adaptation allows a cactus to survive in a hot desert?","explain":"Cacti have deep roots and succulent stems to store water, with spines to reduce water loss.","type":"mcq","options":["Broad flat leaves to absorb sunlight","Deep tap roots and a thick stem to store water","Shedding leaves in the dry season","A relationship with soil decomposers"],"answer":1},{"s":"Geography","t":"Coastal landscapes","q":"Which process involves waves throwing rock fragments against cliffs to wear them away?","explain":"Abrasion occurs when waves hurl sand and pebbles against rock surfaces, grinding them away.","type":"mcq","options":["Attrition","Solution","Abrasion","Hydraulic action"],"answer":2},{"s":"Geography","t":"Coastal landscapes","q":"A spit is formed when longshore drift carries sediment across a bay or river mouth.","explain":"Longshore drift deposits sediment that extends out where the coastline changes direction.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Coastal landscapes","q":"What process smooths and reduces the size of rocks as they collide in the sea?","explain":"Attrition reduces particle size as rocks collide repeatedly, eventually forming sand.","type":"short","accept":["attrition"]},{"s":"Geography","t":"Coastal landscapes","q":"Which coastal management strategy allows the coast to erode and flood naturally?","explain":"Managed retreat accepts erosion and flooding, often creating habitats and saving money.","type":"mcq","options":["Hard engineering","Beach nourishment","Sea wall construction","Managed retreat"],"answer":3},{"s":"Geography","t":"River landscapes","q":"In which part of a river's course is lateral (sideways) erosion most dominant?","explain":"In the lower course the river meanders and erodes its banks laterally.","type":"mcq","options":["Source (upper course)","Middle course","Lower course","Watershed"],"answer":2},{"s":"Geography","t":"River landscapes","q":"An oxbow lake forms when a meander is cut off from the main river channel.","explain":"The river cuts across the meander neck; deposition seals the ends, leaving an oxbow lake.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"River landscapes","q":"What is the flat, fertile land beside a river that is periodically flooded called?","explain":"The floodplain is built up by deposition of alluvium when the river floods.","type":"short","accept":["floodplain","flood plain"]},{"s":"Geography","t":"River landscapes","q":"Which is a hard engineering strategy used to manage flood risk?","explain":"Dams are hard engineering structures that control river flow and reduce flood risk.","type":"mcq","options":["Planting trees in the catchment","Creating wetland buffer zones","Building a dam and reservoir","Restoring river meanders"],"answer":2},{"s":"Geography","t":"UK physical landscapes","q":"Which glacial feature is a steep-sided, armchair-shaped hollow eroded into a mountainside?","explain":"A corrie is a bowl-shaped depression formed by rotational glacial erosion.","type":"mcq","options":["Arete","Pyramidal peak","Corrie","Truncated spur"],"answer":2},{"s":"Geography","t":"UK physical landscapes","q":"The UK's upland landscapes are mainly in the north and west, with lowlands in the south and east.","explain":"Harder, older rocks form uplands in the north and west; softer rocks form southern lowlands.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Urban issues & cities","q":"What population threshold defines a megacity?","explain":"A megacity has a population of 10 million or more.","type":"mcq","options":["1 million","5 million","10 million","20 million"],"answer":2},{"s":"Geography","t":"Urban issues & cities","q":"Urbanisation is currently happening fastest in lower income countries and emerging economies.","explain":"Rural-to-urban migration and population growth make cities in LICs and NEEs grow fastest.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Urban issues & cities","q":"What term is used for the spontaneous, informal settlements that grow on the edges of cities in LICs?","explain":"These develop when rural migrants cannot afford formal housing.","type":"short","accept":["squatter settlements","shanty towns","informal settlements","slums"]},{"s":"Geography","t":"Urban issues & cities","q":"Which of the following is a feature of a sustainable city?","explain":"Mixed land use lets residents live, work and access services locally, cutting transport emissions.","type":"mcq","options":["Expanding out-of-town retail parks","High car dependency","Mixed-use developments reducing the need to travel","Large areas of surface car parking"],"answer":2},{"s":"Geography","t":"The changing economic world","q":"What term describes people and businesses moving from city centres to suburban and rural-urban fringe areas?","explain":"Counter-urbanisation is people leaving cities for suburbs or rural areas.","type":"mcq","options":["Urbanisation","Gentrification","Counter-urbanisation","Re-urbanisation"],"answer":2},{"s":"Geography","t":"The changing economic world","q":"Gentrification typically increases house prices and can displace lower-income residents.","explain":"As wealthier residents move in and improve an area, property values rise.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"The development gap & DTM","q":"At which stage of the Demographic Transition Model are both birth rate and death rate high?","explain":"In Stage 1, high birth rates offset high death rates, so population grows slowly.","type":"mcq","options":["Stage 1","Stage 2","Stage 3","Stage 4"],"answer":0},{"s":"Geography","t":"The development gap & DTM","q":"The Human Development Index (HDI) includes health, education and income indicators.","explain":"HDI combines life expectancy, years of schooling and income per person.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"The development gap & DTM","q":"Which is an example of an INVESTMENT-based approach to reducing the development gap?","explain":"TNCs investing in LICs create jobs, infrastructure and skills - a long-term investment approach.","type":"mcq","options":["Emergency food aid after a drought","Debt relief cancelling loans","A transnational company building a factory in an LIC","Remittances sent home by migrants"],"answer":2},{"s":"Geography","t":"The development gap & DTM","q":"What measures average income per person, calculated by dividing total income by population?","explain":"GDP/GNI per capita is a standard measure of average income used to compare development.","type":"short","accept":["GDP per capita","GNI per capita","gross domestic product per capita","GDP per head","GNI per head"]},{"s":"Geography","t":"Resource management","q":"Which term describes a situation where a country cannot produce or import enough food to feed its population?","explain":"Food insecurity means people lack reliable access to sufficient, nutritious food.","type":"mcq","options":["Food surplus","Food insecurity","Food miles","Food chain"],"answer":1},{"s":"Geography","t":"Resource management","q":"Water stress occurs when demand for water exceeds the available supply.","explain":"Water stress threatens agriculture, industry and health.","type":"mcq","options":["True","False"],"answer":0},{"s":"Geography","t":"Resource management","q":"Which of the following is a RENEWABLE energy source?","explain":"Solar power cannot be depleted; fossil fuels and uranium are finite.","type":"mcq","options":["Natural gas","Coal","Nuclear power","Solar power"],"answer":3},{"s":"Geography","t":"Geographical skills","q":"On a 1:50,000 Ordnance Survey map, what distance on the ground does 2 cm represent?","explain":"At 1:50,000, 1 cm = 500 m, so 2 cm = 1 km.","type":"mcq","options":["500 m","1 km","2 km","5 km"],"answer":1},{"s":"Geography","t":"Geographical skills","q":"On a 1:25,000 OS map, how many metres on the ground does 1 cm represent?","explain":"1 cm represents 25,000 cm = 250 m.","type":"numeric","answer":250,"tolerance":0},{"s":"Geography","t":"Geographical skills","q":"On an OS map, closely spaced contour lines indicate:","explain":"Contour lines close together show a rapid height change - a steep slope.","type":"mcq","options":["A flat, low-lying area","A gentle slope","A steep slope","A river"],"answer":2},{"s":"Geography","t":"Geographical skills","q":"A four-figure grid reference identifies a specific point, while a six-figure reference identifies a 1 km square.","explain":"It is the opposite: four figures give a 1 km square; six figures pinpoint a 100 m location.","type":"mcq","options":["True","False"],"answer":1},{"s":"English","t":"Language techniques","q":"What is a metaphor?","explain":"A metaphor states that one thing is another, unlike a simile which uses 'like' or 'as'.","type":"mcq","options":["A comparison using 'like' or 'as'","A direct comparison that says one thing IS another","Giving human qualities to a non-human thing","Exaggeration for effect"],"answer":1},{"s":"English","t":"Language techniques","q":"Which technique is used in: 'The wind whispered through the trees'?","explain":"Giving the wind a human action ('whispered') is personification.","type":"mcq","options":["Hyperbole","Alliteration","Personification","Oxymoron"],"answer":2},{"s":"English","t":"Language techniques","q":"What is pathetic fallacy?","explain":"Pathetic fallacy uses the environment, especially weather, to mirror an emotional state.","type":"mcq","options":["A logical error made by a character","Using weather or nature to reflect a character's mood","Repetition of vowel sounds within a line","An extended comparison across several lines"],"answer":1},{"s":"English","t":"Language techniques","q":"Which technique is used in: 'Peter Piper picked a peck of pickled peppers'?","explain":"Alliteration is the repetition of the same consonant sound at the start of nearby words.","type":"mcq","options":["Sibilance","Onomatopoeia","Alliteration","Anaphora"],"answer":2},{"s":"English","t":"Language techniques","q":"What is sibilance?","explain":"Sibilance uses soft 's' or 'sh' sounds, often creating a sinister or whispering effect.","type":"mcq","options":["Repetition of hard 'c' or 'k' sounds","Repetition of 's' or 'sh' sounds to create a hissing effect","Extreme exaggeration","A word that sounds like the noise it describes"],"answer":1},{"s":"English","t":"Language techniques","q":"Which technique is used in: 'The bees buzzed busily around the hive'?","explain":"'Buzzed' imitates the sound it describes, making it onomatopoeia.","type":"mcq","options":["Onomatopoeia","Hyperbole","Juxtaposition","Caesura"],"answer":0},{"s":"English","t":"Language techniques","q":"What is hyperbole?","explain":"Hyperbole uses extreme overstatement for emphasis or drama.","type":"mcq","options":["Understatement to downplay a situation","A figure of speech where a part represents the whole","Deliberate exaggeration not meant literally","A reference to another text"],"answer":2},{"s":"English","t":"Language techniques","q":"What is juxtaposition?","explain":"Juxtaposition places contrasting elements together to highlight differences.","type":"mcq","options":["Repetition at the start of successive clauses","Placing two contrasting ideas side by side for effect","A pause created by punctuation mid-line","A word that represents something beyond its literal meaning"],"answer":1},{"s":"English","t":"Language techniques","q":"Which technique is used in the phrase 'deafening silence'?","explain":"An oxymoron places two contradictory words together.","type":"mcq","options":["Metaphor","Anaphora","Oxymoron","Enjambment"],"answer":2},{"s":"English","t":"Language techniques","q":"What is anaphora?","explain":"Anaphora repeats a word or phrase at the start of successive clauses for emphasis.","type":"mcq","options":["A pause in the middle of a line","The repetition of a word or phrase at the start of successive clauses","A comparison using 'like' or 'as'","When a sentence runs past the end of a line"],"answer":1},{"s":"English","t":"Language techniques","q":"What is a semantic field?","explain":"A semantic field is a cluster of related words that builds a theme or atmosphere.","type":"mcq","options":["A group of words linked by a common theme","The literal dictionary meaning of a word","A device linking the end of a text to its start","Giving abstract ideas physical form"],"answer":0},{"s":"English","t":"Language techniques","q":"What is the effect of using a list of three (a tricolon)?","explain":"A rule of three uses rhythm to make ideas feel balanced or increasingly powerful.","type":"mcq","options":["It slows the pace with a pause","It creates rhythm, completeness, or builds to a climax","It compares two contrasting ideas","It gives an abstract concept a physical quality"],"answer":1},{"s":"English","t":"Language techniques","q":"What is the effect of personification in descriptive writing?","explain":"Personification creates an emotional connection by giving non-human subjects human qualities.","type":"mcq","options":["It makes ideas harder to understand","It brings non-human things to life, making them emotionally resonant","It creates a comic effect","It slows the writing by adding syllables"],"answer":1},{"s":"English","t":"Structural techniques","q":"What does 'foreshadowing' mean?","explain":"Foreshadowing plants clues early that prepare the reader for later events.","type":"mcq","options":["Referring back to an earlier event","Describing a setting in detail","Hinting at events that will happen later","Starting in the middle of the action"],"answer":2},{"s":"English","t":"Structural techniques","q":"What is a cyclical structure?","explain":"A cyclical structure returns to the opening idea, suggesting inevitability or reflection.","type":"mcq","options":["A narrative that skips between past and present","A text that ends where it began","A poem with equal stanzas","A story told from multiple perspectives"],"answer":1},{"s":"English","t":"Structural techniques","q":"What does 'in medias res' mean?","explain":"'In medias res' means dropping the reader straight into the action to create tension.","type":"mcq","options":["Ending at a moment of uncertainty","Telling a story in chronological order","Beginning a narrative in the middle of the action","Using a narrator who is also a character"],"answer":2},{"s":"English","t":"Structural techniques","q":"What is caesura in poetry?","explain":"A caesura is a mid-line pause that can create tension or emphasis.","type":"mcq","options":["A sentence continuing past a line break","A pause or break within a line, often from punctuation","Repetition of a vowel sound","A rhyming couplet at the end of a sonnet"],"answer":1},{"s":"English","t":"Structural techniques","q":"What is enjambment?","explain":"Enjambment runs a sentence across line breaks, creating momentum or emphasis.","type":"mcq","options":["A regular alternate rhyme scheme","A sentence continuing beyond the end of a line without a pause","Repetition of consonant sounds","A break in the middle of a line"],"answer":1},{"s":"English","t":"Word classes & sentence types","q":"Which of the following is an imperative sentence?","explain":"An imperative gives a command or instruction, often starting with a verb.","type":"mcq","options":["'The night was very dark.'","'Was the door locked?'","'Run as fast as you can!'","'I think it might rain.'"],"answer":2},{"s":"English","t":"Word classes & sentence types","q":"What effect does a short, simple sentence typically create?","explain":"Short sentences stand out and can create drama, finality or a sudden change of pace.","type":"mcq","options":["A sense of complexity","Impact, shock, or a sudden change in pace","A flowing, musical rhythm","A sense that more information follows"],"answer":1},{"s":"English","t":"Word classes & sentence types","q":"A writer uses verbs like 'slammed', 'crashed' and 'tore'. What class of word are they selecting?","explain":"Action words are verbs; powerful verbs drive pace and energy.","type":"mcq","options":["Adjectives","Adverbs","Verbs","Nouns"],"answer":2},{"s":"English","t":"Punctuation for effect","q":"A writer uses an ellipsis (...) at the end of a sentence. What effect is most likely?","explain":"An ellipsis suggests a pause or that something is left unfinished, building tension.","type":"mcq","options":["A sense of completeness","Suspense, trailing off, or something left unsaid","A list of equally important ideas","Sudden shock"],"answer":1},{"s":"English","t":"Punctuation for effect","q":"What is the effect of a dash used mid-sentence?","explain":"A mid-sentence dash creates a pause and can emphasise what follows.","type":"mcq","options":["It always introduces a list","It creates a pause that can add information or a dramatic interruption","It signals the end of a stanza","It shows a character is speaking"],"answer":1},{"s":"English","t":"Key concepts","q":"What is the difference between 'tone' and 'mood'?","explain":"Tone is the attitude projected; mood is the emotional atmosphere the reader feels.","type":"mcq","options":["They mean the same thing","Tone is the writer's attitude; mood is the atmosphere created for the reader","Tone is the setting; mood is a character's feelings","Tone is for poetry; mood is for prose"],"answer":1},{"s":"English","t":"Key concepts","q":"What does 'writer's intention' mean in an analytical essay?","explain":"Referring to the writer's intention shows that choices are deliberate, not accidental.","type":"mcq","options":["What a character tries to do in the plot","The deliberate choices an author makes to create an effect","The historical background of the text","A summary of the ending"],"answer":1},{"s":"English","t":"Key concepts","q":"'Perspective' and 'narrative viewpoint' both describe the position from which a story is told.","explain":"Both describe the standpoint of narration, e.g. first person or third person omniscient.","type":"mcq","options":["True","False"],"answer":0},{"s":"English","t":"Key concepts","q":"What does 'context' mean when discussing a literary text?","explain":"Context helps explain why a writer chose certain themes, based on the world they lived in.","type":"mcq","options":["The vocabulary level used","The historical, social or cultural circumstances influencing the text","The sequence of plot events","The number of characters"],"answer":1},{"s":"English","t":"Literature: exam approach","q":"How long is AQA GCSE English Literature Paper 1 (Shakespeare and the 19th-century novel)?","explain":"Literature Paper 1 is 1 hour 45 minutes and worth 40% of the GCSE.","type":"mcq","options":["1 hour","1 hour 45 minutes","2 hours 15 minutes","2 hours 45 minutes"],"answer":1},{"s":"English","t":"Literature: exam approach","q":"Which section of AQA Literature Paper 2 contains the unseen poetry questions?","explain":"Section C of Paper 2 tests unseen poetry, including a comparison of two unseen poems.","type":"mcq","options":["Section A","Section B","Section C","Section D"],"answer":2},{"s":"English","t":"Literature: analysis skills","q":"What does the acronym PEEL stand for in analytical writing?","explain":"PEEL (Point, Evidence, Explain, Link) structures analytical paragraphs.","type":"mcq","options":["Point, Evidence, Explain, Link","Plan, Edit, Evaluate, Learn","Purpose, Effect, Example, Language","Paragraph, Evidence, Explore, Literal"],"answer":0},{"s":"English","t":"Literature: analysis skills","q":"In Literature responses, it is good practice to embed short quotations within your own sentences.","explain":"Embedding short quotations shows fluency and is the preferred approach.","type":"mcq","options":["True","False"],"answer":0},{"s":"English","t":"Literature: analysis skills","q":"When tackling an unseen poem, which is the best first step?","explain":"Reading more than once moves you from surface understanding to deeper interpretation.","type":"mcq","options":["Write about the first technique you notice","Read the poem at least twice, considering meaning, tone and structure","Identify the rhyme scheme and write only about that","Ignore the title"],"answer":1},{"s":"English","t":"AQA Language paper structure","q":"In AQA English Language Paper 1, what is the focus of Section A?","explain":"Section A of Language Paper 1 tests reading on a single literary fiction extract.","type":"mcq","options":["Writing: descriptive or narrative tasks","Reading: questions on a literary fiction extract","Reading: comparing two non-fiction texts","Speaking and listening"],"answer":1},{"s":"English","t":"AQA Language paper structure","q":"In AQA English Language Paper 2, which texts are used for the reading section?","explain":"Paper 2 uses two non-fiction texts from different periods to test comparison and synthesis.","type":"mcq","options":["Two literary fiction extracts from the same period","One fiction and one poetry text","Two non-fiction texts from different time periods","One unseen poem and one article"],"answer":2},{"s":"English","t":"AQA Language paper structure","q":"How many marks is Question 5 (the extended writing task) worth on each AQA English Language paper?","explain":"Q5 is worth 40 marks (24 for content, 16 for technical accuracy).","type":"short","accept":["40"]},{"s":"English","t":"Writing skills","q":"What is the purpose of varying sentence length in writing?","explain":"Varied sentence length controls pace: long sentences build atmosphere, short ones create impact.","type":"mcq","options":["To confuse the reader","To control pace, create contrast and keep the reader engaged","To show off vocabulary","To reach the word count"],"answer":1}];
